public class CompoundInterestCalculator {

    public static double balanceAfter(double principal, double annualRate, int years) {
        double balance = principal;
        for (int year = 0; year < years; year++) {
            balance = balance * (1 + annualRate);
        }
        return Math.round(balance * 100.0) / 100.0;
    }

    public static double interestEarned(double principal, double annualRate, int years) {
        double interest = balanceAfter(principal, annualRate, years) - principal;
        return Math.round(interest * 100.0) / 100.0;
    }
}
